select left(git_sha,10) sha, metrics->'producer_identity'->'invocations'->>0 closure0, count(*) runs, min(created_at)::date first_created, max(created_at)::date last_created, min(as_of_date) lo, max(as_of_date) hi, count(*) filter (where jsonb_array_length(metrics->'producer_identity'->'invocations') <> (metrics->'resume'->>'invocations')::int) inv_mismatch, count(*) filter (where (select count(distinct x) from jsonb_array_elements_text(metrics->'producer_identity'->'invocations') x) > 1) mixed from forge_runs where created_at > now() - interval '30 days' and status='succeeded' group by 1,2 order by 4
